<?php require 'config.php';require_role('volunteer');check_csrf();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$code=post('code');if(preg_match('/^(\d+)-([a-f0-9]{8})$/',$code,$m)&&hash_equals(substr(hash('sha256',$m[1]),0,8),$m[2])){
$id=(int)$m[1];$s=db()->prepare("SELECT r.pendaftaran_id,e.tanggal,e.durasi_jam,e.status FROM registrations r JOIN events e ON e.kegiatan_id=r.kegiatan_id WHERE r.volunteer_id=? AND r.kegiatan_id=? AND r.status='Diterima'");$s->execute([user()['user_id'],$id]);$r=$s->fetch();
if($r&&strtotime($r['tanggal'])<=time()&&$r['status']!=='Selesai'){try{db()->prepare("INSERT INTO attendances(pendaftaran_id,waktu_check_in,status_kehadiran) VALUES(?,NOW(),'Hadir')")->execute([$r['pendaftaran_id']]);flash('success','Check-in berhasil dicatat.');redirect('dashboard.php');}catch(Throwable $e){$message='Kehadiran sudah pernah dicatat.';}}else{$message='Pendaftaran tidak ditemukan, belum diterima, atau waktu kegiatan belum dimulai.';}
}else{$message='Kode check-in tidak valid.';}}
layout_start('Check-in');?><div class="page-heading"><span class="eyebrow">ABSENSI KEGIATAN</span><h1>Check-in volunteer</h1><p class="muted">Masukkan kode check-in yang diberikan oleh penyelenggara.</p></div><form class="form-card narrow" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Kode check-in</label><input id="code" name="code" placeholder="Contoh: 12-a1b2c3d4" required><div id="reader" style="width:100%;margin:14px 0"></div><button class="btn btn-outline full" type="button" id="scanbtn">Pindai QR dengan kamera</button><button class="btn btn-primary full">Catat kehadiran</button><script src="https://unpkg.com/html5-qrcode"></script><script>document.getElementById("scanbtn").addEventListener("click",()=>{if(!window.Html5Qrcode){alert("Pemindai QR gagal dimuat. Masukkan kode secara manual.");return;}const scanner=new Html5Qrcode("reader");scanner.start({facingMode:"environment"},{fps:10,qrbox:{width:220,height:220}},text=>{document.getElementById("code").value=text;scanner.stop();},()=>{}).catch(()=>alert("Kamera tidak dapat diakses. Pastikan izin kamera diberikan dan gunakan localhost/HTTPS."));});</script><?php if($message):?><p class="error-text"><?=e($message)?></p><?php endif;?></form><?php layout_end(); ?>